-- Phase 1 definitions: loader-assigned version numbers for suites and tasks and
-- the raw task.yaml (plan 4.5), http MCP headers as {header, env} pairs
-- (plan 5.3), the version a configuration version was duplicated from
-- (plan 6), and what a worker reports about egress and its sandbox (plan 8.7).
--
-- Generated by drizzle-kit, then edited so it also upgrades a database that
-- already holds rows. Suites and tasks are immutable (0001), so their backfill
-- runs with the immutability trigger disabled, inside this migration's
-- transaction: no other session can write while it is off. New NOT NULL
-- columns are added nullable, backfilled, then set NOT NULL.

-- Suites: v1, v2, ... per directory, in the order the versions were loaded.
ALTER TABLE "suites" ADD COLUMN "version_number" integer;--> statement-breakpoint
ALTER TABLE "suites" DISABLE TRIGGER "suites_immutable";--> statement-breakpoint
UPDATE "suites" SET "version_number" = numbered.number
  FROM (SELECT "id", row_number() OVER (PARTITION BY "source_path" ORDER BY "loaded_at", "id") AS number
          FROM "suites") AS numbered
 WHERE "suites"."id" = numbered."id";--> statement-breakpoint
ALTER TABLE "suites" ENABLE TRIGGER "suites_immutable";--> statement-breakpoint
ALTER TABLE "suites" ALTER COLUMN "version_number" SET NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "suites_source_version_uq" ON "suites" USING btree ("source_path","version_number");--> statement-breakpoint
ALTER TABLE "suites" ADD CONSTRAINT "suites_version_number_ck" CHECK ("suites"."version_number" >= 1);--> statement-breakpoint

-- Tasks: each distinct content of a task key in a directory is numbered by its
-- first appearance in suite version order, and introduced by that version.
ALTER TABLE "tasks" ADD COLUMN "version_number" integer;--> statement-breakpoint
ALTER TABLE "tasks" ADD COLUMN "introduced_in_suite_id" text;--> statement-breakpoint
ALTER TABLE "tasks" ADD COLUMN "task_yaml" text;--> statement-breakpoint
ALTER TABLE "tasks" DISABLE TRIGGER "tasks_immutable";--> statement-breakpoint
WITH placed AS (
  SELECT "tasks"."id", "tasks"."key", "tasks"."content_hash", "suites"."source_path",
         "suites"."id" AS suite_id, "suites"."version_number" AS suite_number
    FROM "tasks" JOIN "suites" ON "suites"."id" = "tasks"."suite_id"
), first_seen AS (
  SELECT DISTINCT ON ("source_path", "key", "content_hash")
         "source_path", "key", "content_hash", suite_id AS introduced_in, suite_number AS first_number
    FROM placed
   ORDER BY "source_path", "key", "content_hash", suite_number
), numbered AS (
  SELECT "source_path", "key", "content_hash", introduced_in,
         row_number() OVER (PARTITION BY "source_path", "key" ORDER BY first_number) AS number
    FROM first_seen
)
UPDATE "tasks" SET "version_number" = numbered.number, "introduced_in_suite_id" = numbered.introduced_in
  FROM placed JOIN numbered USING ("source_path", "key", "content_hash")
 WHERE "tasks"."id" = placed."id";--> statement-breakpoint
ALTER TABLE "tasks" ENABLE TRIGGER "tasks_immutable";--> statement-breakpoint
ALTER TABLE "tasks" ALTER COLUMN "version_number" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "tasks" ALTER COLUMN "introduced_in_suite_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_introduced_in_suite_fk" FOREIGN KEY ("introduced_in_suite_id") REFERENCES "public"."suites"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_version_number_ck" CHECK ("tasks"."version_number" >= 1);--> statement-breakpoint

-- MCP: header_names held variable names without the header each one fills, so
-- they cannot become {header, env} pairs. No release wrote MCP definitions, so
-- refuse to guess rather than drop a name silently.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "mcp_server_versions" WHERE cardinality("header_names") > 0) THEN
    RAISE EXCEPTION 'mcp_server_versions.header_names cannot become {header, env} pairs; re-create those definitions';
  END IF;
END;
$$;--> statement-breakpoint
-- ADD and DROP COLUMN fire no row triggers. mcp_server_versions_guard compares
-- to_jsonb(NEW) with to_jsonb(OLD) minus last_test and updated_at, so it covers
-- the new column without change.
ALTER TABLE "mcp_server_versions" DROP CONSTRAINT "mcp_server_versions_shape_ck";--> statement-breakpoint
ALTER TABLE "mcp_server_versions" ADD COLUMN "headers" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "mcp_server_versions" DROP COLUMN "header_names";--> statement-breakpoint
ALTER TABLE "mcp_server_versions" ADD CONSTRAINT "mcp_server_versions_headers_ck" CHECK (jsonb_typeof("mcp_server_versions"."headers") = 'array' and not jsonb_path_exists("mcp_server_versions"."headers", '$[*] ? (!(@.header.type() == "string" && @.env.type() == "string" && @.header like_regex "^[A-Za-z0-9-]{1,64}$" && @.env like_regex "^[A-Z_][A-Z0-9_]*$"))'));--> statement-breakpoint
ALTER TABLE "mcp_server_versions" ADD CONSTRAINT "mcp_server_versions_shape_ck" CHECK (("mcp_server_versions"."transport" = 'stdio' and "mcp_server_versions"."command" is not null and "mcp_server_versions"."command" <> '' and "mcp_server_versions"."url" is null and "mcp_server_versions"."headers" = '[]'::jsonb)
       or ("mcp_server_versions"."transport" = 'http' and "mcp_server_versions"."url" is not null and "mcp_server_versions"."command" is null and cardinality("mcp_server_versions"."args") = 0 and cardinality("mcp_server_versions"."env_names") = 0));--> statement-breakpoint

-- Configurations: a nullable column added without a default fires no trigger,
-- so frozen versions are untouched.
ALTER TABLE "configuration_versions" ADD COLUMN "duplicated_from_version_id" text;--> statement-breakpoint
ALTER TABLE "configuration_versions" ADD CONSTRAINT "configuration_versions_duplicated_from_fk" FOREIGN KEY ("duplicated_from_version_id") REFERENCES "public"."configuration_versions"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint

-- Workers: egress variable names and the last isolation self-test.
ALTER TABLE "workers" ADD COLUMN "egress_env_names" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "workers" ADD COLUMN "sandbox" jsonb;--> statement-breakpoint
ALTER TABLE "workers" ADD CONSTRAINT "workers_sandbox_ck" CHECK ("workers"."sandbox" is null or (jsonb_typeof("workers"."sandbox") = 'object' and ("workers"."sandbox" ->> 'state') in ('isolated', 'failed', 'unavailable')));
